<section class="panel"><div class="panel-head"><div><h2>Menunggu persetujuan</h2><p>Periksa hasil pekerjaan teknisi sebelum disetujui.</p></div></div><?php foreach($tickets as $t): ?><article class="approval-card"><div><b><?= $t->no_tiket ?></b><h3><?= html_escape($t->nama_pelapor) ?> · <?= html_escape($t->nama_jenis) ?></h3><p><?= html_escape($t->deskripsi_aduan) ?></p></div><form method="post" action="<?= site_url('approval/decide/'.$t->id) ?>"><input name="catatan" placeholder="Catatan (opsional)"><button class="button primary" name="decision" value="approve">Setujui</button><button class="button ghost" name="decision" value="reject">Kembalikan</button></form></article><?php endforeach; if(!$tickets): ?><p class="empty">Tidak ada tiket menunggu persetujuan.</p><?php endif; ?></section>
